solution.solution.cpp:
unsigned long long rvaOf(unsigned long long address, unsigned long long base)
{
    return address - base;
}

unsigned long long relocate(unsigned long long stored, unsigned long long preferredBase, unsigned long long actualBase)
{
    return actualBase + (stored - preferredBase);
}

unitTests:
TEST("an RVA") { CHECK_EQ(rvaOf(0x180001234ULL, 0x180000000ULL), 0x1234ULL); }
TEST("RVA of the base") { CHECK_EQ(rvaOf(0x140000000ULL, 0x140000000ULL), 0ULL); }
TEST("moved up") { CHECK_EQ(relocate(0x180001234ULL, 0x180000000ULL, 0x7FF600000000ULL), 0x7FF600001234ULL); }
TEST("moved down") { CHECK_EQ(relocate(0x10002000ULL, 0x10000000ULL, 0x00400000ULL), 0x00402000ULL); }
TEST("not moved") { CHECK_EQ(relocate(0x140005678ULL, 0x140000000ULL, 0x140000000ULL), 0x140005678ULL); }

